import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('full graph ordering differs from pending-only ordering; readiness is current', () => {
  assert.deepEqual(planJobs([job('a', ['z']), job('b'), job('z', [], 'succeeded')]), {
    order: ['b', 'a'], ready: ['a', 'b'], blocked: [],
  });
  assert.deepEqual(planJobs([job('a'), job('s', ['a'], 'succeeded'), job('b', ['s'])]), {
    order: ['a', 'b'], ready: ['a', 'b'], blocked: [],
  });
});

test('all failed ancestors survive completed intermediates and converging paths', () => {
  assert.deepEqual(planJobs([
    job('f', [], 'failed'), job('g', ['f'], 'failed'),
    job('s', ['g'], 'succeeded'), job('p', ['s', 'f']), job('q', ['p', 'g']),
  ]), {
    order: [], ready: [], blocked: [
      { id: 'p', causes: ['f', 'g'] }, { id: 'q', causes: ['f', 'g'] },
    ],
  });
});

test('IDs retain whitespace, Unicode, and object property names without mutation', () => {
  const ids = ['constructor', '__proto__', 'é', 'e\u0301', '😀', '\uffff', ' ', 'A', 'a'];
  const spec = Object.freeze(ids.map(id => Object.freeze({
    ...job(id, Object.freeze([])), ignored: true,
  })));
  const sorted = [...ids].sort();
  assert.deepEqual(planJobs(spec), { order: sorted, ready: sorted, blocked: [] });
  assert.deepEqual(planJobs([job('__proto__', [], 'failed'), job('constructor', ['__proto__'])]), {
    order: [], ready: [], blocked: [{ id: 'constructor', causes: ['__proto__'] }],
  });
});

test('malformed fields and graph errors throw Error', () => {
  const invalid = [null, {}, '[]', [null], [[]], [1], [undefined],
    [{}], [{ id: 'a', deps: [] }], [{ id: 'a', state: 'pending' }],
    [job('')], [job(1)], [job('a', null)], [job('a', 'b')],
    [job('a', [1])], [job('a', [''])], [job('a', [], 'Pending')],
    [job('a', [], null)], [job('a'), job('a')],
    [job('a', ['b', 'b']), job('b')], [job('a', ['missing'])],
    [job('a', ['a'], 'succeeded')],
    [job('ok'), job('a', ['b'], 'failed'), job('b', ['a'], 'succeeded')],
  ];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('deep graphs do not depend on recursive traversal', () => {
  const spec = Array.from({ length: 15000 }, (_, i) => job(String(i), i ? [String(i - 1)] : []));
  const result = planJobs(spec);
  assert.deepEqual(result.order, spec.map(j => j.id));
  assert.deepEqual(result.ready, ['0']);
});

test('CLI handles success, invalid arguments, input errors, and inert imports', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));
  const run = args => spawnSync(process.execPath, args, { encoding: 'utf8' });
  try {
    const good = join(dir, 'good.json');
    const badJson = join(dir, 'bad.json');
    const badGraph = join(dir, 'graph.json');
    writeFileSync(good, JSON.stringify([job('é')]));
    writeFileSync(badJson, '{');
    writeFileSync(badGraph, JSON.stringify([job('a', ['a'])]));
    const success = run([cli, good]);
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, '{"order":["é"],"ready":["é"],"blocked":[]}\n');
    for (const args of [[], [good, good], [join(dir, 'missing')], [badJson], [badGraph]]) {
      const result = run([cli, ...args]);
      assert.equal(result.status, 2);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.length > 0);
    }
    const imported = run(['--input-type=module', '-e', `import ${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)}`]);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
